task.starter_code:
// Platforma beradi:
// const n = 5;
// const word = "JavaScript";
// Kod boshqa qiymatlarda ham tekshiriladi.

// 1. n uchun ko‘paytirish jadvali: 10 ta "5 x 1 = 5" qatori

// 2. let evenSum - 1 dan n gacha juft sonlar yig‘indisi

// 3. let vowelCount - word dagi a, e, i, o, u unlilari (for...of)

task.solution:
// 1. Ko‘paytirish jadvali
for (let i = 1; i <= 10; i++) {
    console.log(`${n} x ${i} = ${n * i}`);
}

// 2. 1 dan n gacha juft sonlar yig‘indisi
let evenSum = 0;
for (let i = 1; i <= n; i++) {
    if (i % 2 === 0) {
        evenSum += i;
    }
}

// 3. So‘zdagi unlilar
const vowels = "aeiou";
let vowelCount = 0;
for (const char of word) {
    if (vowels.includes(char.toLowerCase())) {
        vowelCount++;
    }
}

console.log(`Juftlar yig‘indisi: ${evenSum}, unlilar: ${vowelCount}`);

